#!/usr/bin/env python3
# THE DEUTERONOMY WALK 8b — THE COMPILE OF CHAPTER 10 (2026-09-20; the docket its own run under THE TWO-RUN RULE, on the owner's "The docket go"): THE EXAM
# DOCKET for Deuteronomy 10:1-22, written from the scan's dump (scratchpad/ch10_docket_dump.txt: the LINK rows = every Babylonian Talmud / Mishnah / Tosefta
# segment on the local shelf citing a verse of the chapter — the export's chapter 10 the DB's twenty-two verses; the TOPIC rows = the Mishnah rows, the folio
# ranges of the 8b box's item (n), Seder Olam Rabbah 6, 9 and 10 and Tosefta Sotah 7, read WHOLE; the CREDITED marks = addresses already verdicted in an
# earlier ledger, given their quick look here). Every address in the dump gets ONE verdict (parts A..C on disk, each a SPEC over the dump's own addresses); the
# coverage is COMPUTED from the dump, never typed; the ranges' sizes are read from the scan's own print (ch10_docket_scan.out). Append-only. 7b's form
# (write_ch9_docket.py, derived by asserted substitutions): every row read WHOLE from the start.
import re, os, sys, importlib.util, subprocess
from collections import Counter
ROOT = subprocess.check_output(['git', 'rev-parse', '--show-toplevel'], text=True).strip()   # RUN FROM THE REPO ROOT
SCR = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, SCR)
OUT = f'{ROOT}/logic/oral_triage/deu_10_ekev_exam_2026-09-20.md'
assert not os.path.exists(OUT), OUT
dump = open(f'{SCR}/ch10_docket_dump.txt', encoding='utf-8').read()
rows = re.findall(r'^## \[(LINK|TOPIC)\] (.+?)  (.*)$', dump, re.M)
ADDR, CRED = [], {}
for k, a, rest in rows:
    m = re.search(r'\{CREDITED: (.*?)\}', rest)
    if m: CRED[a.strip()] = m.group(1)
    ADDR.append((k, a.strip(), re.sub(r'\s*\{CREDITED:.*?\}', '', rest).strip()))
NL = sum(1 for k, _, _ in ADDR if k == 'LINK'); NT = len(ADDR) - NL
hdr_line = dump.split('\n', 1)[0]
assert hdr_line == 'ROWS %d LINK %d TOPIC %d CREDITED %d' % (len(ADDR), NL, NT, len(CRED)), (hdr_line, len(ADDR), NL, NT, len(CRED))
V = {}; STATS = []
for p in 'ABC':
    part = f'ch10_docket_{p}'
    spec = importlib.util.spec_from_file_location(part, f'{SCR}/{part}.py'); m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    STATS.append(m.WHOLE_STATS)
    for addr, verdict, note in m.ROWS:
        assert addr not in V, ('duplicate verdict', addr)
        assert verdict in ('LAW', 'DERIVATION', 'DISPUTE', 'CONTEXT', 'OUTSIDE'), (addr, verdict)
        V[addr] = (verdict, note)
missing = [a for _, a, _ in ADDR if a not in V]; extra = [a for a in V if a not in {x[1] for x in ADDR}]
if missing or extra:
    print('MISSING', len(missing), missing); print('EXTRA', len(extra), extra); sys.exit(1)
cnt = Counter(vd for vd, _ in V.values())
cnt_link = Counter(V[a][0] for k, a, _ in ADDR if k == 'LINK'); cnt_topic = Counter(V[a][0] for k, a, _ in ADDR if k == 'TOPIC')
works = Counter(a.rsplit(' ', 1)[0] for k, a, _ in ADDR if k == 'LINK')
scan = open(f'{SCR}/ch10_docket_scan.out', encoding='utf-8').read()
scan_r = scan[scan.index('THE RANGES SIZED:'):]
LONG = [(f'{w.replace("_", " ")} {a}-{z}', int(s), int(l)) for w, a, z, s, l in re.findall(r'^  (\S+)\s+(\d+[ab])-(\d+[ab])\s+(\d+) rows,\s+(\d+) link rows', scan_r, re.M)]   # read from the scan's print
MISH = [a for k, a, _ in ADDR if k == 'TOPIC' and not re.search(r'\d+[ab]:\d+$', a)]   # the Mishnah and midrash rows among the topic rows
assert sum(s - l for _, s, l in LONG) + len(MISH) == NT, (sum(s - l for _, s, l in LONG), len(MISH), NT)   # every range read WHOLE
ncred_link = sum(1 for k, a, _ in ADDR if k == 'LINK' and a in CRED); ncred_topic = sum(1 for k, a, _ in ADDR if k == 'TOPIC' and a in CRED)
verses = Counter(h for k, _, vs in ADDR if k == 'LINK' for h in re.findall(r'Deut 10:\d+', vs)); assert verses, 'no verse hits parsed from the LINK headers'
UNCITED = [v for v in range(1, 23) if f'Deut 10:{v}' not in verses]   # computed, never typed
LAWCELLS = Counter(m.group(1) for vd, note in V.values() if vd == 'LAW' for m in [re.search(r'\b(F[1-6])\b', note)] if m)
TOT = {k: sum(s[k] for s in STATS) for k in STATS[0]}; assert TOT['rows'] == len(ADDR), TOT
NWHOLE = sum(1 for vd, note in V.values() if '[whole:' in note); assert NWHOLE == TOT['corrected'] == 0, (NWHOLE, TOT)
NOUT = Counter(a.rsplit(' ', 1)[0] for a, (vd, _) in V.items() if vd == 'OUTSIDE')
hdr = (f'# THE EXAM DOCKET — Deuteronomy 10:1-22 (the second tablets and the ark — the fragments; the stations and Aaron\'s death — Moserah against Mount Hor, the burial; the Levites separated — to carry, to stand and minister, to bless; the third forty and the command to go; what the LORD asks — the fear, the walk, the love, the service, the heaven of heavens, the fathers chosen, the heart\'s foreskin and the neck; the God of gods — the attributes, the face, the bribe, the orphan and the widow, the stranger loved, the fear, the service, the cleaving, the oath, the praise, the seventy and the stars) — THE DEUTERONOMY WALK sitting 8b, THE DOCKET\'S OWN RUN (2026-09-20; DEUTERONOMY_WALK.md "Sitting 8b — THE COMPILE OF CHAPTER 10 … THE DESIGN", THE ORDER)\n'
       f'# DECLARED: the exam docket is the UNION (the standing rule of 2026-09-05) of (1) THE LINK-DRIVEN ROWS — every segment of the local shelf\'s Babylonian Talmud, Mishnah and Tosefta exports whose English cites a verse of Deuteronomy 10 (the scan ch10_docket_scan.py: {NL} rows in {len(works)} works) — and (2) THE TOPIC ROWS BY ADDRESS, the 8b box\'s item (n) sized by the scan and read WHOLE: Mishnah Shekalim 6:1-6:2, Mishnah Sotah 7:6, Mishnah Berakhot 9:5; the folio ranges {", ".join(n for n, _, _ in LONG)}; Seder Olam Rabbah 6, 9 and 10 whole (the export\'s chapters under its EMPTY key — 7b\'s "unreachable" was the reader\'s index, not the export\'s: the second ascent\'s date read at last) and Tosefta Sotah 7 whole (fifteen rows in the Vilna division; the two arks at 7:9). {len(CRED)} addresses CREDITED (read at an earlier sitting — 7b\'s docket for Menachot 99a-b, chapter 6\'s for Menachot 43b, the erection\'s, the chukat and journeys dockets, the vows\' the largest) and given their quick look here.\n'
       f'# THE TALMUD ADDRESSING: the export\'s index 0 is folio 1a (a page = index // 2 + 1; measured 2026-09-09); the Mishnah by chapter:mishnah; Seder Olam Rabbah and the Tosefta by chapter:row.\n'
       f'# READ WHOLE FROM THE START (THE WHOLE-ROW RULE, owner-ruled 2026-09-17 — "never ever cut corners with the Talmud"): every row was printed WHOLE (ch10_docket_rows.py, N huge; the prints ch10_rows_0_90.txt … ch10_rows_450_540.txt) and read entire before its verdict was typed — no cut, no overlay; the parts\' WHOLE dicts empty, apply_whole\'s counts computed: {TOT["corrected"]} of {TOT["rows"]} rows corrected ({TOT["verdicts_changed"]} verdicts, {TOT["notes_changed"]} notes).\n'
       f'# THE VERDICTS: LAW names the cell of cold_run_second_tablets.py (F1 the_second_tablets_and_the_ark, F2 the_stations_and_aarons_death, F3 the_levites_separated, F4 the_third_forty_and_the_go, F5 what_the_lord_asks, F6 the_god_of_gods_and_the_stranger) or the callee\'s cell by CALL; DERIVATION a hook from the verse to a rule; DISPUTE a parameter row with two arms; CONTEXT; OUTSIDE a declared range\'s matter on another subject. The link census: LAW {cnt_link.get("LAW", 0)} / DERIVATION {cnt_link.get("DERIVATION", 0)} / DISPUTE {cnt_link.get("DISPUTE", 0)} / CONTEXT {cnt_link.get("CONTEXT", 0)} / OUTSIDE {cnt_link.get("OUTSIDE", 0)}; the topic census: LAW {cnt_topic.get("LAW", 0)} / DERIVATION {cnt_topic.get("DERIVATION", 0)} / DISPUTE {cnt_topic.get("DISPUTE", 0)} / CONTEXT {cnt_topic.get("CONTEXT", 0)} / OUTSIDE {cnt_topic.get("OUTSIDE", 0)}; LAW by cell {dict(sorted(LAWCELLS.items()))}. The verses cited by the link rows: {", ".join(f"{v} ({n})" for v, n in sorted(verses.items(), key=lambda kv: int(kv[0].split(":")[1])))}; UNCITED by any row: {UNCITED}.\n')
body = ''
last = None
for k, a, vs in ADDR:
    work = a.rsplit(' ', 1)[0]
    if work != last:
        body += f'\n## {work}\n'; last = work
    vd, note = V[a]
    body += f'- {a} [{k}{(" — " + vs) if vs else ""}{(" — CREDITED: " + CRED[a]) if a in CRED else ""}] — {vd}. {note}\n'
crowns = '''
## The finds (this docket's crowns)
- THE ARK IS ONE IN THE BAVLI'S OWN WORDS, TWO IN THE TOSEFTA'S (Bava Batra 14a:8; Yoma 3b:3, 72b:8; Menachot 28b:2; Tosefta Sotah 7:9): "the ark of the covenant THAT MOSES FASHIONED — two and a half cubits its length" — Exodus 25:10's measures in Moses' name, 10:3's "I made" and 25:10's "they shall make" one vessel (the attribution by Israel's conduct; Moses built and all supported; a vessel fit for the generations); against it R. Yehuda ben Lakish's TWO ARKS — one to war with the Torah scroll (Numbers 10:33), one in the camp with the broken tablets (Numbers 14:44): THE PARAMETER'S TWO ARMS — the design's decision (1) stands on the Bavli, the Tosefta's arm a DISPUTE row and the exam's row.
- THE FRAGMENTS IN THE ARK — THREE DERIVATIONS, AND WHAT ELSE THE ARK HELD (Bava Batra 14a:9-14b:7; Menachot 99a:12; Berakhot 8b:7): Rav Yosef's baraita on 10:1-2 ("which you broke, and you shall put THEM in the ark" — both sets), Rav Huna's 2 Samuel 6:2 ("the Name, the Name" — R. Meir's source), R. Yehuda's 1 Kings 8:9 ("nothing … except" — E4, a restriction after a restriction extends); R. Meir's ark (the cubit six): fifteen by nine by nine handbreadths, the tablets six by six by three, twelve along the length, TWO HANDBREADTHS FOR THE TORAH SCROLL INSIDE beside the tablets (31:26's "at the side" read of the tablets' side); R. Yehuda's (the cubit five): twelve and a half by seven and a half, the silver columns inside, the scroll on the Philistines' chest OUTSIDE (1 Samuel 6:8): THE EFFECT fragments_in_the_ark's VALUE — the tablets and the fragments (both arms), the scroll inside or beside (the parameter); the elder who forgot honored for it (8b:7, 99a:12 — the sanctity rule "one elevates, never degrades", 99a:9-11); the breaking approved at its third seat (14b:7, 99b:1 — credited).
- THE SECOND ASCENT'S DATE — MATCH (Seder Olam Rabbah 6:2, read whole for the first time — the export's chapters under the empty key): up the seventh day after the Ten Words; down the 17th of Tammuz and the tablets broken; up the 18th of Tammuz (9:25); DOWN THE 28TH OF AV AND CARVED (34:4); UP THE 29TH OF AV (10:10 — "as at the first days": the first and the third of favor, the middle of anger); down the 10th of Tishri, Yom Kippur, the pardon announced (34:9; Leviticus 16:34 the fixed day): THE MACHINE'S (1, 5, 29) BY SUBTRACTION IS SEDER OLAM'S OWN DATE — 7b's OPEN row on the clock ("the tradition's first of Elul") CLOSED: that date is not this shelf's text; the tape's morrow (1, 4, 18) MATCH too; the hewing on the 28th a day before the ascent (the tape's marker at 34:4 the 29th for both — a DATA note, no change); DB4 asserts the match; 7b's owed item (iii) PAID.
- THE LEVITES' SEPARATION READ FOR THE BLESSING (Sotah 38a:5, 38a:8; Arakhin 11a:10; Ta'anit 26b:17; Zevachim 16a:13; Horayot 13a:18; Pesachim 104a:10; Mishnah Sotah 7:6; Tosefta Sotah 7:5): the shelf reads 10:8's third office from its second — the blessing STANDING like the service, with LIFTED HANDS (18:5's "him and his sons forever" juxtaposed through 10:8's pair), not itself "service" (service and blessing named apart — the Levites' song the service with the Name), permitted after grape pits, "before the LORD" the Temple (a seated rite fit at a private altar); the rank — Levite before Israelite (13a:18; the two distinctions, 104a:10); the form (the Name in the Temple, the hands above the head, the High Priest not above the frontplate; the blemished on face, hands or feet excluded; the hands alike in the provinces) — naso.blessing by CALL holds it; "WHICH TIME" ASKED BY NO ROW — the tape's own answer (invested_office on the Levites at the calf's morrow) stands unopposed.
- THE FEAR OF HEAVEN — THE ONE FREE VARIABLE (Berakhot 33b:23-25; Megillah 25a:9-10; Niddah 16b:13; Shabbat 31b:1-3; Menachot 43b:15-18; Sotah 11a:5): "everything is in the hands of Heaven except the fear of Heaven" from 10:12 at three seats — the asking proves the choice is man's: THE EFFECT fear_of_heaven_asked NAMED BY THE SHELF; "is it a small thing?" — His treasury holds it alone (Isaiah 33:6); for Moses it is (the vessel parable, E26); the outer key to the treasury; the man who fears sin above the man of Torah; a hundred blessings from "what" (the do-not-read reading ma / me'a named, no code) and the three daily blessings.
- THE HEART'S FORESKIN GUARDED BY GRAMMAR (Shabbat 108a:7; Sukkah 52a:7): Karna — "say the circumcision is on the heart, 'circumcise the foreskin [orlat] of your heart' (10:16)"; Rav: the verbal analogy (I2) takes the complete form orlato / orlato (Leviticus 12:3, 19:23), never the construct orlat (nor Jeremiah 6:10's areila) — 10:16 IS NOT THE CIRCUMCISION LAW'S OBJECT: the heart's line writes its own effect, never circumcision_due; the heart's foreskin is THE EVIL INCLINATION, Moses' name for it among its seven (52a:7) — the effect heart_circumcision_commanded's value.
- THE ATTRIBUTES: THREE AND NO MORE; THE FACE THRICE RECONCILED (Yoma 69b:13-16; Berakhot 33b:18, 33b:21-22; Megillah 25a:4, 25a:7-8; Rosh Hashanah 17b:17; Niddah 70b:5; Berakhot 20b:15; Megillah 31a:13): Moses wrote "the great, the mighty and the awesome" (10:17) and the great assembly fixed them — Jeremiah dropped "awesome" and Daniel "mighty", speaking no falsehood; the assembly re-founded the might on patience and the awesomeness on Israel's survival; the leader who adds is rebuked (the exam's person; the attributes decrees, not mercies); "lifts no face" against Numbers 6:26 — before / after the sentence (R. Yehoshua to the Alexandrians), the angels answered by Israel's grace after an olive-bulk beyond 8:10's "satisfied" (good_land by CALL), the Sifrei 42:2's "when Israel do His will" (naso's DATA): THE THREE RECONCILIATIONS; the greatness beside the humility at three seats (31a:13).
- THE BRIBE — EVEN TO JUDGE TRULY, EVEN BY WORDS (Ketubot 105a:8-105b:17): Karna's istera from each party — "you shall take no bribe" (Exodus 23:8) even to acquit the innocent (the baraita against 16:19's "wrest"); a salary voids the judgment (Kiddushin 58b), evident compensation for lost work allowed (Karna's wine, Rav Huna's water-drawer); the bribe blinds — a fortiori the fools (I1), the wise to folly and the righteous to dementia; SHOCHAD = SHE-HU CHAD (E30, the notarikon — one mind with the giver); the borrowing judge disqualified; BRIBERY BY WORDS ("no bribe", not "no profit") — Shmuel's hand out of the ferry, Ameimar's feather, Mar Ukva's spittle, R. Yishmael's sharecropper, R. Yishmael bar Elisha's first shearing, Rav Anan's fish, each judge disqualified: THE EXAM'S PERSONS for ordinances.courts by CALL (10:17's "takes no bribe" God's attribute; 23:8 the law's seat; 16:19 forward).
- THE STRANGER — THIRTY-SIX WARNINGS AND THE INTAKE (Bava Metzia 59b:12-15; Yevamot 47a:1-47b:19): wronging by words three prohibitions (Exodus 22:20; Leviticus 19:33, 25:17), oppressing three (Exodus 22:20, 23:9, 22:24); R. Eliezer the Great's thirty-six (or forty-six) warnings — because his inclination is evil; R. Natan on "for you were strangers" — A DEFECT THAT IS IN YOU, DO NOT MENTION IT IN ANOTHER (the hanged man's adage): THE REASON CLAUSE'S RULE at 10:19 (the Sifra's "know the stranger's soul from your own" the cell's value); the convert's evidence in the land or abroad (R. Yehuda / the Rabbis — a DISPUTE), the convert in court (1:16 — opening_speech by CALL), the private convert credible against himself, not his children (21:17 — a DISPUTE); THE INTAKE — "what did you see?", the lenient and the stringent, the poor's gifts, the punishments and the reward, no overwhelming, circumcision at once and the shreds, immersion when healed before three, the woman, the slave; Naomi's dialogue with Ruth; the returning convert a Jew still; the beautiful captive (a DISPUTE): the exam's persons for the stranger's line (love_owed; holiness_b.convert_measures by CALL); Isaiah 14:1's "cleave" [venispechu] the cleaving's homograph, named.
- THE CLEAVING, THE "ET" AND THE OATH — AND THE POSITIVE FORM (Ketubot 111b:6-8; Sotah 14a:3-4, 14a:6; Pesachim 22b:11; Temurah 3b:17, 4a:2; Sanhedrin 56a:10-11; Shevuot 35b:22-27): cleave to a devouring fire? — marry a daughter to a scholar, trade for scholars, benefit scholars — "as though cleaving to the Presence" (4:4 and 30:20 read; 10:20 the command's first seat, 11:22 and 13:5 between): THE EFFECT cleaving_commanded's VALUE; "walk after the LORD" (13:5) = His attributes — clothe the naked, visit the sick, console the mourner, BURY THE DEAD ("and He buried him", 34:6 — the Torah begins and ends with kindness): 10:12's "walk in all His ways" and 10:18's bread and clothing the kin, the burial beside 10:6's passive "and he was buried there"; Shimon HaAmmassoni withdrew at 10:20's "et" — R. Akiva: the Torah scholars (E1, the extension) feared as God; "by His name you shall swear" — a truthful oath permitted (3b:17; the oath to keep the commandments, Psalm 119:106); "YOU SHALL FEAR THE LORD YOUR GOD" A WARNING STATED AS A POSITIVE COMMAND, no prohibition's warning (Temurah 4a:2; Sanhedrin 56a:11): THE FORM RULE — 10:20's four clauses positive, the writes STATUS not BLOCK, no lashes; the oath of testimony by the appellations liable (35b:22), ala / ala (I2) with the sota.
- THE SEVENTY AND THE SEVENTIETH (Bava Batra 123a:21-123b:1; Seder Olam Rabbah 9:2): seventy in the total, sixty-nine by name; Dinah's twin ("ET his daughter" — E1) refuted by Benjamin's "et"; R. Chama bar Chanina's pearl — JOCHEBED, conceived on the way and born between the walls ("born to Levi in Egypt", Numbers 26:59): the Joseph runner's cell 'jochebed' by CALL; Seder Olam names Serah and Jochebed among those who came to Egypt and those who left it: 10:22's "with seventy persons your fathers went down" the count's own DATA row.
- AARON'S DEATH, THE CLOUDS AND THE RETREAT (Rosh Hashanah 3a:1-13; Ta'anit 9a:9-12; Seder Olam Rabbah 9:2, 10:2): Arad heard that Aaron died and the clouds of glory departed (the do-not-read "they saw" / "they were seen" named, no code; ki = because among Reish Lakish's four senses); Sihon = Arad = Canaan; the era's years from Nisan by the chain that runs through Numbers 33:38 (the fortieth year, the fifth month, the first) and Deuteronomy 1:3; the three sustainers' three gifts — the cloud by Aaron's merit, gone at his death, returned by Moses'; Miriam in Nisan, AARON IN AV, Moses in Adar (Zechariah 11:8's "one month" the gifts' common end; the editor's "first of Tammuz" variant a DATA note beside the tape's (40, 5, 1)); THE RETREAT OF SEVEN STATIONS read whole — "did Aaron die in Moserah? did he not die at the hill of the mountain? rather, from where Aaron died they retreated seven stations until Moserah" — the parameter's own row, the OPEN row's shelf source (no marker for the retreat; decision (4) stands); Moses died and was born the seventh of Adar (10:2).
- WHAT THE DESIGN DID NOT PREDICT (carried to RUN B as DATA rows or notes): THE SECOND ASCENT'S DATE MATCHES SEDER OLAM (the OPEN row on the clock CLOSED — DB4 asserts the match on the running world; 7b's item (iii) PAID); the Tosefta's TWO ARKS on the shelf (the parameter's second arm — a DISPUTE row, the exam's row); WHAT THE ARK HELD — the scroll inside or beside, the silver columns (R. Meir / R. Yehuda) — the effect's value's second parameter; the heart's foreskin excluded from the circumcision law BY THE CONSTRUCT FORM (Shabbat 108a:7); the heart's foreskin = the evil inclination (Sukkah 52a:7 — the effect's value); "walk after Him" = bury the dead (Sotah 14a:4 — beside 10:6's passive burial); the four clauses' POSITIVE FORM (Temurah 4a:2; Sanhedrin 56a:11) — STATUS confirmed; the converts' intake the stranger line's exam; Seder Olam's Aaron "first of Av" with the editor's variant; no row asks "which time" for the Levites; Isaiah 14:1's venispechu the cleaving's homograph.
'''
cite = '\n## CITE INDEX — every segment opened, each fully named\n(coverage COMPUTED by write_ch10_docket.py against the scan\'s dump: %d addresses, every one verdicted — missing 0, extra 0)\n' % len(ADDR)
cite += '\n'.join(a for _, a, _ in ADDR) + '\n'
tail = (f'\n**read: {len(ADDR)} of {len(ADDR)} — COMPLETE** (the link-driven rows {NL}: {", ".join(f"{k} {n}" for k, n in sorted(cnt_link.items()))}; '
        f'the topic windows {NT}: {", ".join(f"{k} {n}" for k, n in sorted(cnt_topic.items()))}; all rows: {", ".join(f"{k} {n}" for k, n in sorted(cnt.items()))}; credited {len(CRED)} — the counts this script computed from the dump and the verdict lists, never typed; every row read WHOLE from the start, corrections {TOT["corrected"]}; the ranges: {"; ".join(f"{n} {s} rows ({l} link)" for n, s, l in LONG)}; the Mishnah and midrash rows {len(MISH)}; OUTSIDE by work: {dict(NOUT)}.)\n')
open(OUT, 'w', encoding='utf-8').write(hdr + body + crowns + cite + tail)
print('WROTE', OUT, os.path.getsize(OUT), 'bytes')
print('rows', len(ADDR), 'link', NL, 'topic', NT, 'credited', len(CRED), '(link', ncred_link, 'topic', ncred_topic, ')')
print('verdicts', dict(sorted(cnt.items())), 'link', dict(sorted(cnt_link.items())), 'topic', dict(sorted(cnt_topic.items())))
print('LAW by cell', dict(sorted(LAWCELLS.items())))
print('OUTSIDE by work', dict(NOUT))
print('verses cited', sorted(verses.items(), key=lambda kv: int(kv[0].split(':')[1])), 'UNCITED', UNCITED)
print('ranges', [(n, s, l) for n, s, l in LONG]); print('mishnah+midrash rows', len(MISH))
